window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e24f72dedd456807"]={"versions": [{"id": "FIG-e24f72dedd456807", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Methodik-Aktivitätendiagramm (SPEM-/Methodology-Notation). Das Schaubild stellt die methodische Aktivität „Define Software Component Timing“ im Kontext des Software-Komponenten-Designs und der Timing-Spezifikation dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Rolle</strong>:\n<ul class=\"fig-list\"><li><code>Software Component Developer</code>: Führt die Aktivität aus (<code>«performs»</code>).\n</li></ul>\n</li><li><strong>Aktivität</strong>:\n<ul class=\"fig-list\"><li><code>Define Software Component Timing</code>: Zentrale Arbeitsaufgabe zur Erstellung bzw. Verfeinerung von Timing-Beschreibungen auf Software-Komponenten-Ebene.\n</li></ul>\n</li><li><strong>Artefakte / Work Products</strong>:\n<ul class=\"fig-list\"><li><code>Software Component Internal Behavior</code> (Eingangsartefakt, Kardinalität <code>1</code>, Stereotyp <code>«input»</code>): Spezifikation des internen Verhaltens der Software-Komponente.\n</li><li><code>VFB Timing</code> (Eingangsartefakt, Kardinalität <code>0..1</code>, Stereotyp <code>«input»</code>): Optionale übergeordnete Timing-Vorgaben aus dem Virtual Function Bus.\n</li><li><code>Software Component Timing</code> (Ausgangsartefakt, Kardinalität <code>1</code>, Stereotyp <code>«output»</code>; Text im Bild am rechten Rand als <code>Software Compo...</code> abgeschnitten): Resultierende Timing-Beschreibung der Software-Komponente.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>Software Component Developer</code> initiiert und führt die Aktivität <code>Define Software Component Timing</code> durch.\n</li><li>Als verbindliche Eingabe dient genau eine Spezifikation des <code>Software Component Internal Behavior</code> (<code>1</code>).\n</li><li>Optional kann maximal eine übergeordnete <code>VFB Timing</code>-Spezifikation (<code>0..1</code>) als Entwurfsbasis bzw. Randbedingung einbezogen werden.\n</li><li>Das Ergebnis der Durchführung ist genau eine konsolidierte Spezifikation des <code>Software Component Timing</code> (<code>1</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Die Aktivität definiert den formalen Übergang vom internen Komponentenverhalten (und optionalen VFB-Timing-Vorgaben) zur detaillierten Komponenten-Timing-Beschreibung.\n</li><li>Die Multiplizität <code>0..1</code> bei <code>VFB Timing</code> kennzeichnet diesen Input als optional; die Definition von Software-Komponenten-Timing kann demnach auch isoliert auf Basis des internen Komponentenverhaltens erfolgen.\n</li><li>Der Ausgang <code>Software Component Timing</code> ist mit Kardinalität <code>1</code> obligatorisch für den Abschluss der Entwurfsphase auf Komponentenebene.\n</li></ul>"}, {"id": "FIG-5faec67200eccb88", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Methodik-Aktivitätendiagramm (SPEM-/Methodology-Notation). Das Schaubild stellt die methodische Aktivität „Define Software Component Timing“ im Kontext des Software-Komponenten-Designs und der Timing-Spezifikation dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Rolle</strong>:\n<ul class=\"fig-list\"><li><code>Software Component Developer</code>: Führt die Aktivität aus (<code>«performs»</code>).\n</li></ul>\n</li><li><strong>Aktivität</strong>:\n<ul class=\"fig-list\"><li><code>Define Software Component Timing</code>: Zentrale Arbeitsaufgabe zur Erstellung bzw. Verfeinerung von Timing-Beschreibungen auf Software-Komponenten-Ebene.\n</li></ul>\n</li><li><strong>Artefakte / Work Products</strong>:\n<ul class=\"fig-list\"><li><code>Software Component Internal Behavior</code> (Eingangsartefakt, Kardinalität <code>1</code>, Stereotyp <code>«input»</code>): Spezifikation des internen Verhaltens der Software-Komponente.\n</li><li><code>VFB Timing</code> (Eingangsartefakt, Kardinalität <code>0..1</code>, Stereotyp <code>«input»</code>): Optionale übergeordnete Timing-Vorgaben aus dem Virtual Function Bus.\n</li><li><code>Software Component Timing</code> (Ausgangsartefakt, Kardinalität <code>1</code>, Stereotyp <code>«output»</code>; Text im Bild am rechten Rand als <code>Software Compo...</code> abgeschnitten): Resultierende Timing-Beschreibung der Software-Komponente.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>Software Component Developer</code> initiiert und führt die Aktivität <code>Define Software Component Timing</code> durch.\n</li><li>Als verbindliche Eingabe dient genau eine Spezifikation des <code>Software Component Internal Behavior</code> (<code>1</code>).\n</li><li>Optional kann maximal eine übergeordnete <code>VFB Timing</code>-Spezifikation (<code>0..1</code>) als Entwurfsbasis bzw. Randbedingung einbezogen werden.\n</li><li>Das Ergebnis der Durchführung ist genau eine konsolidierte Spezifikation des <code>Software Component Timing</code> (<code>1</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Die Aktivität definiert den formalen Übergang vom internen Komponentenverhalten (und optionalen VFB-Timing-Vorgaben) zur detaillierten Komponenten-Timing-Beschreibung.\n</li><li>Die Multiplizität <code>0..1</code> bei <code>VFB Timing</code> kennzeichnet diesen Input als optional; die Definition von Software-Komponenten-Timing kann demnach auch isoliert auf Basis des internen Komponentenverhaltens erfolgen.\n</li><li>Der Ausgang <code>Software Component Timing</code> ist mit Kardinalität <code>1</code> obligatorisch für den Abschluss der Entwurfsphase auf Komponentenebene.\n</li></ul>"}, {"id": "FIG-f0f75b6229dcb378", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Methodik-Aktivitätendiagramm (SPEM-/Methodology-Notation). Das Schaubild stellt die methodische Aktivität „Define Software Component Timing“ im Kontext des Software-Komponenten-Designs und der Timing-Spezifikation dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Rolle</strong>:\n<ul class=\"fig-list\"><li><code>Software Component Developer</code>: Führt die Aktivität aus (<code>«performs»</code>).\n</li></ul>\n</li><li><strong>Aktivität</strong>:\n<ul class=\"fig-list\"><li><code>Define Software Component Timing</code>: Zentrale Arbeitsaufgabe zur Erstellung bzw. Verfeinerung von Timing-Beschreibungen auf Software-Komponenten-Ebene.\n</li></ul>\n</li><li><strong>Artefakte / Work Products</strong>:\n<ul class=\"fig-list\"><li><code>Software Component Internal Behavior</code> (Eingangsartefakt, Kardinalität <code>1</code>, Stereotyp <code>«input»</code>): Spezifikation des internen Verhaltens der Software-Komponente.\n</li><li><code>VFB Timing</code> (Eingangsartefakt, Kardinalität <code>0..1</code>, Stereotyp <code>«input»</code>): Optionale übergeordnete Timing-Vorgaben aus dem Virtual Function Bus.\n</li><li><code>Software Component Timing</code> (Ausgangsartefakt, Kardinalität <code>1</code>, Stereotyp <code>«output»</code>; Text im Bild am rechten Rand als <code>Software Compo...</code> abgeschnitten): Resultierende Timing-Beschreibung der Software-Komponente.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>Software Component Developer</code> initiiert und führt die Aktivität <code>Define Software Component Timing</code> durch.\n</li><li>Als verbindliche Eingabe dient genau eine Spezifikation des <code>Software Component Internal Behavior</code> (<code>1</code>).\n</li><li>Optional kann maximal eine übergeordnete <code>VFB Timing</code>-Spezifikation (<code>0..1</code>) als Entwurfsbasis bzw. Randbedingung einbezogen werden.\n</li><li>Das Ergebnis der Durchführung ist genau eine konsolidierte Spezifikation des <code>Software Component Timing</code> (<code>1</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Die Aktivität definiert den formalen Übergang vom internen Komponentenverhalten (und optionalen VFB-Timing-Vorgaben) zur detaillierten Komponenten-Timing-Beschreibung.\n</li><li>Die Multiplizität <code>0..1</code> bei <code>VFB Timing</code> kennzeichnet diesen Input als optional; die Definition von Software-Komponenten-Timing kann demnach auch isoliert auf Basis des internen Komponentenverhaltens erfolgen.\n</li><li>Der Ausgang <code>Software Component Timing</code> ist mit Kardinalität <code>1</code> obligatorisch für den Abschluss der Entwurfsphase auf Komponentenebene.\n</li></ul>"}], "trans": [{"from": "FIG-e24f72dedd456807", "to": "FIG-5faec67200eccb88", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-5faec67200eccb88", "to": "FIG-f0f75b6229dcb378", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
